  const v25 = []; for (const m of s.matchAll(/\[AUDIT v25: RECOMPUTED AFTER CURE -- [^\n]*?TRIGGER: ([^\n]*?); ORIGINAL: ([^;\n]*); RECOMPUTED: ([^;\n]*);/g)) v25.push({ k: 2, trig: m[1].trim(), of: W(m[2]), to: W(m[3]), ro: R(m[2]), rt: R(m[3]) });
