const rmWhy = x => { const n = +x.drv_uncured || 0; const L = drvUnc(x.verdict_raw); if (L.length !== n && Array.isArray(x.removed_rules) && x.removed_rules.length && +x.removed_rules_total === n) return 'NOT COUNTED: ' + n + ' debate rule violation' + (n === 1 ? '' : 's') + ' not cured (' + x.removed_rules.join('; ') + '; the record names the rule and the count, not the item)'; return notCountedWhy({ ...x, truncated: false, drv_uncured: n }); };
